def load_json_data(path):
    """Load JSON data from file."""
    with open(path, 'r', encoding='utf-8') as f:
        return json.load(f)

def find_xml_files(directory):
    """Find all XML files in directory recursively."""
    xml_files = []
    for root, dirs, files in os.walk(directory):
        for f in files:
            if f.endswith('.xml'):
                xml_files.append(os.path.join(root, f))
    return xml_files

def has_placeholder(text):
    """Check if text contains {{placeholder}} pattern."""
    if text is None:
        return False
    return bool(re.search(r'\{\{[^}]+\}\}', text))

def replace_placeholders_in_text(text, replacements):
    """Replace all {{key}} with values in text."""
    if text is None:
        return text
    result = text
    for key, value in replacements.items():
        pattern = '{{' + key + '}}'
        result = result.replace(pattern, value)
    return result

def process_xml_file(filepath, replacements):
    """
    Process an XML file:
    1. Check for fragmented placeholders across <hp:t> elements
    2. Replace placeholders in <hp:t> elements
    3. Remove <hp:linesegarray> from modified paragraphs
    """
    with open(filepath, 'r', encoding='utf-8') as f:
        original_content = f.read()

    # Parse XML
    parser = etree.XMLParser(remove_blank_text=False)
    try:
        tree = etree.parse(filepath, parser)
    except Exception as e:
        print(f"Error parsing {filepath}: {e}")
        return False

    root = tree.getroot()
    modified = False

    # Find all paragraphs
    paragraphs = root.findall('.//hp:p', NAMESPACES)

    for para in paragraphs:
        # Get all text elements in this paragraph
        text_elements = para.findall('.//hp:t', NAMESPACES)

        if not text_elements:
            continue

        # Check for fragmented placeholders by joining all text
        joined_text = ''.join(t.text or '' for t in text_elements)

        if has_placeholder(joined_text):
            # This paragraph contains placeholders - need to process

            # Step 1: Consolidate fragmented placeholders
            # If a placeholder spans multiple <hp:t>, consolidate into first
            full_text = joined_text

            # Check if we need to consolidate
            if len(text_elements) > 1:
                # Simple approach: check if {{ and }} are in different elements
                first_has_open = False
                last_has_close = False

                for i, t in enumerate(text_elements):
                    text = t.text or ''
                    if '{{' in text:
                        first_has_open = True
                    if '}}' in text:
                        last_has_close = True

                # If placeholder is fragmented, consolidate to first element
                if first_has_open and last_has_close:
                    # Consolidate all text into first element
                    text_elements[0].text = full_text
                    # Clear other elements
                    for t in text_elements[1:]:
                        t.text = ''

            # Step 2: Replace placeholders in all <hp:t> elements
            para_modified = False
            for t in text_elements:
                if t.text and has_placeholder(t.text):
                    new_text = replace_placeholders_in_text(t.text, replacements)
                    if new_text != t.text:
                        t.text = new_text
                        para_modified = True

            # Step 3: Remove lineSegArray from modified paragraph
            if para_modified:
                line_seg_arrays = para.findall('hp:linesegarray', NAMESPACES)
                for lsa in line_seg_arrays:
                    para.remove(lsa)
                modified = True

    # Write back if modified
    if modified:
        tree.write(filepath, encoding='utf-8', xml_declaration=True)
        return True
    return False

def verify_no_placeholders(directory):
    """Verify no {{ placeholders remain in any file."""
    remaining = []
    for root, dirs, files in os.walk(directory):
        for f in files:
            filepath = os.path.join(root, f)
            try:
                with open(filepath, 'r', encoding='utf-8') as file:
                    for i, line in enumerate(file, 1):
                        if '{{' in line or '}}' in line:
                            remaining.append((filepath, i, line.strip()))
            except:
                pass
    return remaining

def create_zip(source_dir, output_path):
    """Create ZIP file from directory contents."""
    with zipfile.ZipFile(output_path, 'w', zipfile.ZIP_DEFLATED) as zf:
        for root, dirs, files in os.walk(source_dir):
            for f in files:
                full_path = os.path.join(root, f)
                arcname = os.path.relpath(full_path, source_dir)
                zf.write(full_path, arcname)

def main():
    print("Loading JSON data...")
    replacements = load_json_data(JSON_PATH)
    print(f"Found {len(replacements)} replacements: {list(replacements.keys())}")

    print("\nFinding XML files...")
    xml_files = find_xml_files(TEMPLATE_DIR)
    print(f"Found {len(xml_files)} XML files: {[os.path.basename(f) for f in xml_files]}")

    print("\nProcessing XML files for placeholder replacement...")
    modified_files = []
    for xml_file in xml_files:
        result = process_xml_file(xml_file, replacements)
        if result:
            modified_files.append(xml_file)
            print(f"  Modified: {os.path.basename(xml_file)}")

    print(f"\nModified {len(modified_files)} files")

    print("\nVerifying no placeholders remain...")
    remaining = verify_no_placeholders(TEMPLATE_DIR)
    if remaining:
        print("WARNING: The following placeholders remain:")
        for filepath, line, content in remaining:
            print(f"  {filepath}:{line}: {content[:100]}")
    else:
        print("  All placeholders replaced successfully!")

    print("\nCreating output ZIP file...")
    create_zip(TEMPLATE_DIR, OUTPUT_PATH)
    print(f"  Created: {OUTPUT_PATH}")

    print("\nDone!")

if __name__ == '__main__':
    main()
